
declare namespace SigUtils {
    /**
     * This namespace provides type definitions for all gesture event detail properties.
     * Usage: (event: CustomEvent<SigUtils.Gestures.TrackEventDetail>) => { ... }
    */
    export namespace Gestures {
        /**
         * Detail object for the 'on-tap' gesture event.
         * @property x X position of the pointer.
         * @property y Y position of the pointer.
         */
        interface TapEventDetail {
            x: number;
            y: number;
        }

        /**
         * Detail object for the 'on-down' gesture event.
         * @property x X position of the pointer.
         * @property y Y position of the pointer.
         */
        interface DownEventDetail {
            x: number;
            y: number;
        }

        /**
         * Detail object for the 'on-up' gesture event.
         * @property x X position of the pointer.
         * @property y Y position of the pointer.
         */
        interface UpEventDetail {
            x: number;
            y: number;
        }

        /**
         * Detail object for the 'on-track' gesture event.
         * @property x X position of the pointer.
         * @property y Y position of the pointer.
         * @property dx Relative X position from gesture start.
         * @property dy Relative Y position from gesture start.
         * @property ddx Relative X position from last tracking point.
         * @property ddy Relative Y position from last tracking point.
         */
        interface TrackEventDetail {
            x: number;
            y: number;
            dx: number;
            dy: number;
            ddx: number;
            ddy: number;
        }

        /**
         * Detail object for the 'on-longpress' gesture event.
         * @property x X position of the pointer.
         * @property y Y position of the pointer.
         */
        interface LongPressEventDetail {
            x: number;
            y: number;
        }

        /**
         * Detail object for the 'on-pinchzoom' gesture event.
         * @property x X position of the pointer.
         * @property y Y position of the pointer.
         * @property dx Relative X position from gesture start.
         * @property dy Relative Y position from gesture start.
         * @property ddx Relative X position from last tracking point.
         * @property ddy Relative Y position from last tracking point.
         * @property dist Distance between two pointers (sqrt of sum of squares).
         * @property distfactor -1 for pinch, +1 for zoom.
         * @property rotation Two finger delta angle during gesture in radians.
         * @property rotationstart Two finger angle at start of gesture in radians.
         */
        interface PinchZoomEventDetail {
            x: number;
            y: number;
            dx: number;
            dy: number;
            ddx: number;
            ddy: number;
            dist: number;
            distfactor: number;
            rotation: number;
            rotationstart: number;
        }
    }
}
